        KJGrammar(id: "n4_ka_dou_ka", lv: 4, pat: "〜かどうか", m: ["whether or not", "是否～", "~인지 아닌지"], tip: ["A yes/no question inside a sentence.", "句中的是非疑問。", "문장 속의 예/아니요 질문."], ex: [KJEx(ja: "{彼|かれ}が~{来|く}る[[かどうか]]~わかりません。", en: "I don't know whether he will come.", zh: "不知道他會不會來。", ko: "그가 올지 안 올지 모르겠습니다."), KJEx(ja: "おいしいか~どうか、~{食|た}べてみてください。", en: "Try it and see whether it tastes good.", zh: "請吃吃看好不好吃。", ko: "맛있는지 어떤지 먹어 보세요.")], decoys: ["のに", "ので", "ために"]),
