        KJGrammar(id: "n4_noun_ka", lv: 4, pat: "〜の（名詞化）", m: ["~ing (making a verb a noun)", "把動詞變名詞（の）", "~하는 것 (명사화)"], tip: ["Plain form + の / こと turns an action into a noun.", "普通形＋の／こと：把動作名詞化。", "보통형 + の/こと: 동작을 명사로."], ex: [KJEx(ja: "{私|わたし}は~{絵|え}を~かく[[の]]が~{好|す}きです。", en: "I like drawing pictures.", zh: "我喜歡畫畫。", ko: "저는 그림 그리는 것을 좋아합니다."), KJEx(ja: "{日本語|にほんご}を~{話|はな}すのは~むずかしいです。", en: "Speaking Japanese is difficult.", zh: "說日語很難。", ko: "일본어를 말하는 것은 어렵습니다.")], decoys: ["を", "に", "と"]),
