        KJGrammar(id: "n4_toki", lv: 4, pat: "〜とき", m: ["when ~", "～的時候", "~할 때"], tip: ["る+とき = before it happens. た+とき = after it happened.", "辭書形＋とき：事前；た形＋とき：事後。", "사전형 + とき: 하기 전, た형 + とき: 한 후."], ex: [KJEx(ja: "{日本|にほん}へ~{行|い}った[[とき]]、~{友|とも}だちに~{会|あ}いました。", en: "When I went to Japan, I met a friend.", zh: "我去日本的時候見了朋友。", ko: "일본에 갔을 때 친구를 만났습니다."), KJEx(ja: "{寝|ね}るとき、~「おやすみなさい」と~{言|い}います。", en: "When going to bed, we say \"Good night.\"", zh: "睡覺時說「晚安」。", ko: "잘 때 \"안녕히 주무세요\"라고 합니다.")], decoys: ["ので", "まで", "から"]),
        KJGrammar(id: "n4_aida", lv: 4, pat: "〜あいだ／〜あいだに", m: ["while ~ / during", "在～期間（一直／某時）", "~하는 동안 / ~하는 사이에"], tip: ["あいだ = the whole time. あいだに = at some point during.", "あいだ：整段期間；あいだに：期間中的某時。", "あいだ: 그동안 내내, あいだに: 그 사이 어느 때."], ex: [KJEx(ja: "{夏休|なつやす}みの[[あいだに]]、~{運転|うんてん}{免許|めんきょ}を~とりました。", en: "I got my driver's license during summer vacation.", zh: "暑假期間考到了駕照。", ko: "여름 방학 동안에 운전면허를 땄습니다."), KJEx(ja: "{母|はは}が~{料理|りょうり}を~している~あいだ、~{私|わたし}は~そうじを~しました。", en: "While my mother was cooking, I cleaned.", zh: "媽媽做菜的時候，我在打掃。", ko: "어머니가 요리하는 동안 저는 청소를 했습니다.")], decoys: ["までに", "ながら", "ために"]),
